@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Rye&family=Special+Elite&display=swap');
:root{--ink:#f4dfb2;--cream:#e9d4ad;--rust:#bd5d3d;--gold:#e4b85d;--dark:#171d1a;--line:rgba(242,218,176,.23)}*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#171d1a;color:var(--ink);font-family:'DM Mono',monospace;touch-action:none}.game-shell{position:relative;width:100vw;height:100dvh;min-height:320px;overflow:hidden;background:#b98a53;isolation:isolate}#game{display:block;width:100%;height:100%;object-fit:cover;image-rendering:pixelated;image-rendering:crisp-edges;background:#c89454}.vignette{position:absolute;inset:0;pointer-events:none;background:radial-gradient(ellipse at center,transparent 42%,rgba(17,21,18,.27) 100%);z-index:1}.topbar{position:absolute;z-index:3;top:0;left:0;right:0;height:68px;padding:0 36px;display:flex;align-items:center;justify-content:space-between;background:linear-gradient(180deg,rgba(18,24,21,.8),transparent);transition:opacity .3s}.brand{font-family:'Rye',serif;font-size:15px;letter-spacing:1.6px;color:#f1ddba}.brand i{font-style:normal;color:var(--rust)}.brand-mark{display:inline-flex;align-items:center;justify-content:center;width:25px;height:25px;margin-right:10px;border:1px solid #d29d61;border-radius:50%;font-size:14px;color:#dda65f}.chapter,.small-hint,.title-foot,.micro-label,.controls-tip{font-size:9px;letter-spacing:1.3px}.chapter{color:#d2c2a2}.chapter span{color:#ba6746;margin:0 8px}.icon-btn{width:34px;height:34px;border:1px solid var(--line);border-radius:50%;background:#272722aa;color:var(--cream);font-size:18px;cursor:pointer}.hud{position:absolute;z-index:3;top:82px;left:32px;right:32px;display:flex;gap:12px;align-items:flex-start;transition:opacity .2s}.hud-card{background:rgba(25,30,26,.84);border:1px solid rgba(239,210,164,.34);padding:10px 13px;box-shadow:3px 3px 0 rgba(26,22,18,.18);backdrop-filter:blur(4px)}.health-card{min-width:116px}.micro-label{display:block;font-size:8px;letter-spacing:1.7px;color:#c3a778;margin-bottom:5px}.hearts{display:flex;gap:4px;color:#d96d51;font-size:14px;letter-spacing:1px}.objective-card{width:min(270px,42vw)}.objective-card strong{font-family:'Special Elite',serif;font-size:13px;font-weight:400}.progress-line{height:3px;background:#64533a;margin-top:8px}.progress-line span{display:block;height:100%;width:0;background:#d6a354;transition:width .3s}.ammo-card{margin-left:auto;min-width:95px}.ammo-card strong{font-family:'Rye',serif;color:#f1dda8;font-size:16px}.ammo-card small{font-family:'DM Mono',monospace;font-size:8px;letter-spacing:1px;color:#c3a778}.screen{position:absolute;inset:0;z-index:4}.hidden{display:none!important}.title-screen{display:flex;align-items:center;background:linear-gradient(90deg,rgba(18,23,20,.89) 0%,rgba(24,27,22,.72) 39%,rgba(23,24,20,.04) 100%)}.title-copy{margin-left:clamp(34px,10.5vw,160px);margin-top:24px;max-width:510px}.eyebrow{display:flex;align-items:center;gap:10px;color:#d19a58;font-size:9px;letter-spacing:2.1px}.eyebrow span{width:22px;height:1px;background:#bd694a}h1{font-family:'Rye',serif;font-weight:400;font-size:clamp(46px,8vw,95px);line-height:.96;letter-spacing:1px;margin:20px 0 15px;color:#f0d7a8;text-shadow:3px 4px 0 rgba(46,27,19,.65)}h1 em,.end-panel h2 em{font-style:normal;color:#c86d47}.tagline{font-family:'Special Elite',serif;font-size:16px;color:#d5c09b;margin:0 0 32px}.primary-btn{min-width:232px;height:48px;display:flex;align-items:center;justify-content:space-between;padding:0 16px;border:1px solid #e6bd77;background:#a74e36;color:#fff0d4;box-shadow:4px 4px 0 #392920;font:500 10px 'DM Mono',monospace;letter-spacing:1.4px;cursor:pointer;transition:transform .15s,background .15s}.primary-btn b{font-size:20px;font-weight:400}.primary-btn:hover{transform:translate(-2px,-2px);background:#c06140;box-shadow:6px 6px 0 #392920}.small-hint{margin-top:22px;color:#bcaa8b;font-size:8px}.title-stamp{position:absolute;right:clamp(35px,10vw,145px);top:25%;width:125px;height:125px;border:2px solid rgba(173,78,50,.72);outline:1px solid rgba(173,78,50,.72);outline-offset:5px;border-radius:50%;display:grid;place-content:center;text-align:center;transform:rotate(12deg);color:#bf6545;font:15px 'Rye',serif;line-height:1.25;opacity:.8}.title-stamp b{font:8px 'DM Mono',monospace;letter-spacing:1px;margin-top:7px}.title-foot{position:absolute;bottom:22px;left:36px;right:36px;display:flex;justify-content:space-between;color:#c4ad88;font-size:8px}.story-screen{z-index:5;background:rgba(11,14,13,.28);display:flex;align-items:flex-end;justify-content:center}.cinema-bars{position:absolute;left:0;right:0;height:7vh;background:#101411;z-index:0}.cinema-bars.top{top:0}.cinema-bars.bottom{bottom:0}.story-card{position:relative;width:min(760px,84vw);margin-bottom:13vh;padding:23px 28px 17px;border-left:2px solid #c46c47;background:rgba(20,25,22,.9);box-shadow:0 10px 30px #0005}.story-kicker{font-size:9px;letter-spacing:2px;color:#d5a25e;margin-bottom:12px}.story-text{min-height:70px;font:18px/1.5 'Special Elite',serif;color:#f0dfbf;max-width:650px}.story-bottom{display:flex;justify-content:space-between;align-items:center;margin-top:12px;color:#ad9a79;font-size:9px;letter-spacing:1px}.text-btn{border:0;background:transparent;color:#e8c98e;font:10px 'DM Mono',monospace;letter-spacing:1.4px;cursor:pointer;padding:9px}.text-btn b{font-size:17px;margin-left:10px}.pause-screen,.end-screen{z-index:6;display:grid;place-items:center;background:rgba(16,21,18,.78);backdrop-filter:blur(3px)}.pause-panel,.end-panel{text-align:center;width:min(480px,88vw);padding:42px 25px;background:#252921eF;border:1px solid #9a7951;box-shadow:7px 7px 0 #151713}.pause-panel .eyebrow,.end-panel .eyebrow{justify-content:center}.pause-panel h2{font:42px 'Rye',serif;margin:13px 0}.pause-panel>p:not(.eyebrow),.end-panel>p:not(.eyebrow){font:15px 'Special Elite',serif;color:#c9b797;margin:8px auto 24px}.pause-panel .primary-btn,.end-panel .primary-btn{margin:0 auto}.restart-btn{display:block;margin:13px auto 0}.end-panel h2{font:clamp(27px,5vw,43px)/1.2 'Rye',serif;margin:20px 0;color:#f0d7a8}.touch-controls{position:absolute;z-index:3;inset:auto 0 0;height:190px;pointer-events:none;display:flex;justify-content:space-between;align-items:end;padding:0 7vw max(22px,env(safe-area-inset-bottom))}.stick-zone{position:relative;width:130px;height:155px;display:flex;flex-direction:column;align-items:center;justify-content:flex-end;gap:5px;pointer-events:auto;color:#f2dfbd;font-size:8px;letter-spacing:1.5px;touch-action:none}.stick-base{width:100px;height:100px;border-radius:50%;border:1px solid #f1d29a88;background:#2427208c;display:grid;place-items:center;box-shadow:inset 0 0 0 8px #f1d29a12}.stick-knob{width:41px;height:41px;border-radius:50%;background:#dfbd82bb;border:1px solid #f6e2bb;box-shadow:0 3px 7px #0006;transform:translate(0,0)}.touch-actions{display:flex;gap:12px;align-items:flex-end;pointer-events:auto}.touch-btn{width:68px;height:68px;border-radius:50%;background:#332c24c9;border:1px solid #e4c28c;color:#f3dfb8;display:flex;flex-direction:column;justify-content:center;align-items:center;gap:2px;touch-action:none;box-shadow:0 3px 0 #171713}.touch-btn span{font-size:22px}.touch-btn small{font:7px 'DM Mono',monospace;letter-spacing:.5px}.shoot-touch{width:78px;height:78px;background:#9f4b39d9}.interact-touch{width:58px;height:58px;margin-bottom:8px}.controls-tip{position:absolute;z-index:2;bottom:14px;left:50%;transform:translateX(-50%);white-space:nowrap;color:#e6d5b6;background:#171c19c2;padding:8px 13px;border:1px solid #d7bc8c44;font-size:8px}.controls-tip i{color:#cf8055;font-style:normal;padding:0 5px}.toast{position:absolute;z-index:4;top:28%;left:50%;transform:translate(-50%,-50%);padding:12px 20px;background:#20251ee8;border:1px solid #d3a865;color:#f0d7a8;font:13px 'Special Elite',serif;box-shadow:4px 4px 0 #171713;white-space:nowrap;animation:toastIn .25s ease-out}.fade-layer{position:absolute;z-index:10;inset:0;background:#111713;opacity:0;pointer-events:none;transition:opacity .45s}.fade-layer.active{opacity:1}.title-screen~.touch-controls{display:none}@keyframes toastIn{from{opacity:0;transform:translate(-50%,-43%)}to{opacity:1;transform:translate(-50%,-50%)}}@media(max-width:700px){.topbar{height:54px;padding:0 17px}.brand{font-size:12px}.brand-mark{width:21px;height:21px;margin-right:6px}.chapter{display:none}.title-copy{margin-left:8vw;margin-top:0}.title-copy .eyebrow{font-size:7px;letter-spacing:1.5px}.tagline{font-size:14px;margin-bottom:24px}.title-stamp{width:84px;height:84px;right:10vw;top:17%;font-size:10px}.title-stamp b{font-size:6px}.title-foot{left:16px;right:16px;font-size:6px;bottom:12px}.hud{top:62px;left:12px;right:12px;gap:6px}.hud-card{padding:7px 9px}.health-card{min-width:86px}.hearts{font-size:12px}.micro-label{font-size:7px}.objective-card{width:min(205px,46vw)}.objective-card strong{font-size:11px}.ammo-card{min-width:67px}.ammo-card strong{font-size:13px}.ammo-card small{font-size:7px}.touch-controls{height:158px;padding-left:4vw;padding-right:4vw}.stick-zone{width:112px;height:135px}.stick-base{width:86px;height:86px}.stick-knob{width:38px;height:38px}.touch-actions{gap:7px}.touch-btn{width:57px;height:57px}.shoot-touch{width:68px;height:68px}.controls-tip{display:none!important}.story-card{width:91vw;margin-bottom:12vh;padding:17px 18px}.story-text{font-size:15px;min-height:86px}.story-kicker{font-size:8px}.story-bottom{font-size:8px}.primary-btn{min-width:210px;height:45px}.small-hint{font-size:6px}.ammo-card .micro-label{letter-spacing:1px}}
@media(max-height:500px) and (orientation:landscape){.title-copy{margin-left:8vw}.title-copy h1{font-size:48px;margin:10px 0}.tagline{font-size:12px;margin-bottom:12px}.primary-btn{height:40px}.small-hint{margin-top:10px}.title-stamp{width:80px;height:80px;top:15%}.touch-controls{height:125px;padding-bottom:8px}.stick-zone{height:110px}.stick-base{width:72px;height:72px}.stick-knob{width:32px;height:32px}.touch-btn{width:51px;height:51px}.shoot-touch{width:59px;height:59px}.hud{top:55px}.story-card{margin-bottom:9vh;padding:13px 18px}.story-text{min-height:50px;font-size:14px}}

(() => {
  'use strict';
  const canvas = document.getElementById('game'), ctx = canvas.getContext('2d');
  const $ = id => document.getElementById(id);
  const ui = {title:$('titleScreen'), story:$('storyScreen'), pause:$('pauseScreen'), end:$('endScreen'), hud:$('hud'), top:$('topbar'), touch:$('touchControls'), tip:$('controlsTip'), fade:$('fadeLayer'), toast:$('toast'), hearts:$('hearts'), objective:$('objective'), progress:$('progress'), storyText:$('storyText'), storyKicker:$('storyKicker'), storyCount:$('storyCount')};
  const TILE=16, MAP_W=60, MAP_H=42, WORLD_W=MAP_W*TILE, WORLD_H=MAP_H*TILE;
  let W=480,H=270, state='title', seed=0, last=performance.now(), elapsed=0, toastTimer=0, cinematicTimer=0, storyPage=0;
  let keys={}, mouse={x:0,y:0,down:false,active:false}, touchMove={x:0,y:0}, touchFire=false, touchInteract=false, muted=true, audio=null;
  let camera={x:0,y:0}, player, enemies=[], bullets=[], props=[], decor=[], fragments=[], particles=[], bell={x:480,y:320}, victory=false, kills=0;
  const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
  const hash=(x,y,s=seed)=>{let n=Math.imul(x|0,374761393)+Math.imul(y|0,668265263)+Math.imul(s|0,1442695041)|0;n=Math.imul(n^(n>>>13),1274126177);return((n^(n>>>16))>>>0)/4294967295};
  const rnd=()=>{seed=(Math.imul(seed,1664525)+1013904223)|0;return(seed>>>0)/4294967295};
  const dist=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y);
  const showToast=(text,duration=2.2)=>{ui.toast.textContent=text;ui.toast.classList.remove('hidden');toastTimer=duration};
  const sound=(freq=440,duration=.08,type='square',volume=.035)=>{if(muted)return;try{audio??=new (window.AudioContext||window.webkitAudioContext)();const o=audio.createOscillator(),g=audio.createGain();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(volume,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+duration);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+duration)}catch{}};
  function resize(){const r=canvas.getBoundingClientRect();const ratio=clamp(r.width/Math.max(1,r.height),.58,2.7);H=270;W=Math.round(H*ratio);canvas.width=W;canvas.height=H}
  addEventListener('resize',resize,{passive:true});resize();
  function makeWorld(){
    props=[];decor=[];fragments=[];enemies=[];bullets=[];particles=[];kills=0;victory=false;
    const locations=[{x:210,y:152,name:'Cementerio',type:'grave'},{x:780,y:145,name:'Mina abandonada',type:'mine'},{x:760,y:520,name:'Oasis seco',type:'oasis'}];
    locations.forEach((p,i)=>{const a= i===0?0.35:i===1?2.45:4.7;fragments.push({x:p.x,y:p.y,got:false,place:p.name,phase:rnd()*6.28});for(let j=0;j<3;j++){const ang=a+j*2.15;enemies.push({x:p.x+Math.cos(ang)*(34+j*9),y:p.y+Math.sin(ang)*(27+j*7),hp:2,max:2,kind:j===2?'shotgun':'bandit',speed:22+rnd()*10,phase:rnd()*6.28,alive:true,alert:false})}});
    // Around town, the last outlaw only appears after the three letters are found.
    enemies.push({x:bell.x+34,y:bell.y-7,hp:7,max:7,kind:'boss',speed:18,phase:0,alive:false,alert:false});
    player={x:465,y:390,faceX:0,faceY:-1,hp:5,maxHp:5,invuln:0,fire:0,walk:0,hitFlash:0};
    for(let i=0;i<230;i++){
      const x=24+rnd()*(WORLD_W-48),y=24+rnd()*(WORLD_H-48);
      if(Math.hypot(x-480,y-320)<100||locations.some(p=>Math.hypot(x-p.x,y-p.y)<46))continue;
      const roll=rnd();props.push({x,y,type:roll<.38?'cactus':roll<.62?'rock':roll<.8?'bush':'bones',scale:.7+rnd()*.8,flip:rnd()<.5});
    }
    for(let i=0;i<18;i++)decor.push({x:480+(rnd()-.5)*155,y:320+(rnd()-.5)*120,type:i%3,phase:rnd()*6.28});
    bell={x:480,y:320};player.x=bell.x-18;player.y=bell.y+64;
  }
  function startGame(){seed=(Date.now()^Math.floor(Math.random()*0x7fffffff))|0;makeWorld();state='story';storyPage=0;ui.title.classList.add('hidden');ui.end.classList.add('hidden');ui.pause.classList.add('hidden');ui.hud.classList.remove('hidden');ui.tip.classList.toggle('hidden',isTouchDevice());ui.touch.classList.toggle('hidden',!isTouchDevice());ui.top.style.opacity='1';setStoryPage();fadeTransition();}
  function isTouchDevice(){return matchMedia('(pointer:coarse)').matches||navigator.maxTouchPoints>0}
  const storyPages=[
    ['RED ROCK, TERRITORIO DE ARIZONA','Hace siete años, Mara Vale dejó Red Rock con una promesa y una estrella de sheriff. Hoy, una carta sin remitente la trae de vuelta.'],
    ['UNA CARTA BAJO LA PUERTA','«La campana sigue muda. Silas Crowe tomó el pueblo y guarda la verdad en tres cartas. Si aún recuerdas a tu hermano, ven antes del último tren.»'],
    ['EL SOL NO ESPERA','El pueblo se deshace bajo el polvo. Encuentra las cartas, limpia el camino y haz sonar la vieja campana. Algunas promesas todavía pueden cumplirse.']
  ];
  function setStoryPage(){ui.storyKicker.textContent=storyPages[storyPage][0];ui.storyText.textContent='';ui.storyCount.textContent=`0${storyPage+1} / 03`;ui.story.classList.remove('hidden');cinematicTimer=0;}
  function advanceStory(){if(state!=='story')return;if(storyPage<storyPages.length-1){storyPage++;setStoryPage()}else{state='play';ui.story.classList.add('hidden');showToast('ENCUENTRA LAS TRES CARTAS · MIRA EL MAPA',3);sound(392,.25,'triangle')}}
  function fadeTransition(){ui.fade.classList.add('active');setTimeout(()=>ui.fade.classList.remove('active'),420)}
  function updateHud(){ui.hearts.innerHTML=Array.from({length:player.maxHp},(_,i)=>`<span style="opacity:${i<player.hp?1:.24}">♥</span>`).join('');const got=fragments.filter(f=>f.got).length;ui.progress.style.width=`${got/3*100}%`;ui.objective.textContent=got<3?`Encuentra las cartas · ${got}/3`:victory?'Haz sonar la campana':'Vence a Silas Crowe'};}
  function togglePause(){if(state==='play'){state='paused';ui.pause.classList.remove('hidden');ui.touch.classList.add('hidden');sound(180,.13,'triangle')}else if(state==='paused'){state='play';ui.pause.classList.add('hidden');ui.touch.classList.toggle('hidden',!isTouchDevice());sound(260,.1,'triangle')}}
  function endGame(won){state='ending';ui.end.classList.remove('hidden');ui.hud.classList.add('hidden');ui.touch.classList.add('hidden');ui.tip.classList.add('hidden');$('endTitle').innerHTML=won?'LA CAMPANA<br><em>VUELVE A SONAR</em>':'EL POLVO<br><em>TE CUBRE</em>'; $('endCopy').textContent=won?'Red Rock recuerda tu nombre. Y, por fin, descansa.':'El desierto se queda con otra historia. Pero siempre hay otro amanecer.';fadeTransition();sound(won?523:110,.5,'triangle',.05)}
  function nearestEnemy(){let best=null,d=Infinity;for(const e of enemies)if(e.alive){const n=Math.hypot(e.x-player.x,e.y-player.y);if(n<d){best=e;d=n}}return best}

function interact(){
  if(state!=='play')return;
  for(const f of fragments){if(!f.got&&Math.hypot(f.x-player.x,f.y-player.y)<34){f.got=true;const n=fragments.filter(v=>v.got).length;showToast(n<3?`CARTA ${n} DE 3 · UN NOMBRE: ${n===1?'ELENA':n===2?'JONAH':'MARA'}`:'LAS TRES CARTAS REUNIDAS',2.8);sound(690,.12,'sine');for(let i=0;i<16;i++)particles.push({x:f.x,y:f.y,vx:(rnd()-.5)*70,vy:(rnd()-.5)*70,life:.8,color:'#f4d18a'});if(n===3){const boss=enemies.find(e=>e.kind==='boss');boss.alive=true;boss.x=bell.x+42;boss.y=bell.y-8;boss.alert=true;showToast('SILAS CROWE TE ESPERA EN EL PUEBLO',3.3)}updateHud();return}}
  if(fragments.every(f=>f.got)&&victory&&Math.hypot(bell.x-player.x,bell.y-player.y)<65){endGame(true);return}
  const near=nearestEnemy();if(near&&Math.hypot(near.x-player.x,near.y-player.y)<42){showToast('¡DISPARA PARA ABRIRTE PASO!',1.4);return}
  if(Math.hypot(bell.x-player.x,bell.y-player.y)<66&&!fragments.every(f=>f.got)){showToast('LAS CARTAS ESTÁN ESCONDIDAS POR EL DESIERTO',2)}
}
function shoot(dx,dy){if(player.fire>0)return;player.fire=.25;let aimX=dx,aimY=dy;if(!Number.isFinite(aimX)||!Number.isFinite(aimY)){const target=nearestEnemy();if(target&&Math.hypot(target.x-player.x,target.y-player.y)<260){aimX=target.x-player.x;aimY=target.y-player.y}else{aimX=player.faceX;aimY=player.faceY}}const m=Math.hypot(aimX,aimY)||1;aimX/=m;aimY/=m;player.faceX=aimX;player.faceY=aimY;bullets.push({x:player.x+aimX*9,y:player.y+aimY*8,vx:aimX*240,vy:aimY*240,life:.8});sound(125,.075,'sawtooth',.025);for(let i=0;i<3;i++)particles.push({x:player.x+aimX*10,y:player.y+aimY*8,vx:aimX*(35+rnd()*40)+(rnd()-.5)*20,vy:aimY*(35+rnd()*40)+(rnd()-.5)*20,life:.15+rnd()*.12,color:'#ffd580'})}
function hurt(){if(player.invuln>0)return;player.hp--;player.invuln=1.1;player.hitFlash=.22;showToast('¡CUIDADO, FORASTERA!',1.1);sound(90,.18,'square',.045);updateHud();const enemy=nearestEnemy();if(enemy){const dx=player.x-enemy.x,dy=player.y-enemy.y,d=Math.hypot(dx,dy)||1;player.x+=dx/d*13;player.y+=dy/d*13}if(player.hp<=0)setTimeout(()=>{if(state==='play')endGame(false)},450)}
function pollGamepad(){const gp=navigator.getGamepads?.()[0];if(!gp)return{mx:0,my:0,fire:false,interact:false,pause:false,aimX:0,aimY:0};const ax=gp.axes[0]||0,ay=gp.axes[1]||0,rx=gp.axes[2]||0,ry=gp.axes[3]||0;return{mx:Math.abs(ax)>.16?ax:0,my:Math.abs(ay)>.16?ay:0,fire:!!(gp.buttons[7]?.pressed||gp.buttons[2]?.pressed),interact:!!gp.buttons[0]?.pressed,pause:!!gp.buttons[9]?.pressed,aimX:Math.abs(rx)>.25?rx:0,aimY:Math.abs(ry)>.25?ry:0}}
let padPrev={a:false,start:false};
function update(dt){
  elapsed+=dt;if(toastTimer>0&&(toastTimer-=dt)<=0)ui.toast.classList.add('hidden');
  if(state==='story'){cinematicTimer+=dt;const full=storyPages[storyPage][1],count=Math.min(full.length,Math.floor(cinematicTimer*38));ui.storyText.textContent=full.slice(0,count);return}
  if(state!=='play')return;
  const gp=pollGamepad();if(gp.pause&&!padPrev.start)togglePause();if(gp.interact&&!padPrev.a)interact();padPrev={a:gp.interact,start:gp.pause};if(state!=='play')return;
