'use strict';

const canvas=document.getElementById('game'),ctx=canvas.getContext('2d');
ctx.imageSmoothingEnabled=false;
const $=id=>document.getElementById(id);
const W=480,H=270,WORLD_W=960,WORLD_H=640,TILE=16,MAP_W=WORLD_W/TILE,MAP_H=WORLD_H/TILE;
const ui={toast:$('toast'),hud:$('hud'),title:$('titleScreen'),story:$('storyScreen'),storyText:$('storyText'),storyKicker:$('storyKicker'),storyCount:$('storyCount'),pause:$('pauseScreen'),end:$('endScreen'),endTitle:$('endTitle'),endCopy:$('endCopy'),fade:$('fadeLayer'),touch:$('touchControls'),tip:$('controlsTip'),topbar:$('topbar')};
let state='title',storyPage=0,cinematicTimer=0,elapsed=0,toastTimer=0,muted=false,kills=0,victory=false;
let camera={x:0,y:0},bullets=[],particles=[],bells={};
const keys={},mouse={x:0,y:0,down:false,active:false},touchMove={x:0,y:0};
let touchFire=false,touchInteract=false;
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
let seed=1887;
function rnd(){seed=(seed*1664525+1013904223)%4294967296;return seed/4294967296}
function hash(x,y){let n=(x*374761393+y*668265263+seed)%2147483647;n=(n^(n>>13))*1274126177;return ((n^(n>>16))>>>0)/4294967295}

const storyPages=[
 ['RED ROCK, TERRITORIO DE ARIZONA','1887. Red Rock cerró sus puertas con el último redoble de una campana que nunca debía tocarse.'],
 ['LA PROMESA DE UNA HERMANA','Mara volvió buscando respuestas. Tres cartas, una por cada alma perdida, señalan el camino hasta Silas Crowe.'],
 ['AL OTRO LADO DEL POLVO','Encuentra las cartas, enfrenta a los hombres de Crowe y devuelve a Red Rock su campana.']
];
const player={x:480,y:390,hp:5,maxHp:5,fire:0,invuln:0,hitFlash:0,faceX:1,faceY:0,walk:0};
const bell={x:480,y:320};
const fragments=[
 {x:220,y:150,place:'Cementerio',got:false,phase:.2},
 {x:780,y:175,place:'Mina abandonada',got:false,phase:1.4},
 {x:685,y:500,place:'Oasis seco',got:false,phase:2.5}
];
const enemies=[
 {x:300,y:320,hp:2,alive:true,alert:false,speed:24,kind:'bandit',phase:0},
 {x:610,y:230,hp:2,alive:true,alert:false,speed:25,kind:'bandit',phase:1},
 {x:720,y:420,hp:2,alive:true,alert:false,speed:23,kind:'bandit',phase:2},
 {x:370,y:520,hp:2,alive:true,alert:false,speed:26,kind:'bandit',phase:3},
 {x:522,y:362,hp:8,alive:false,alert:false,speed:30,kind:'boss',phase:4}
];
const props=[];
for(let i=0;i<110;i++){let x=12+rnd()*(WORLD_W-24),y=12+rnd()*(WORLD_H-24);if(Math.hypot(x-480,y-320)<90||fragments.some(f=>Math.hypot(x-f.x,y-f.y)<35))continue;const r=rnd();props.push({x,y,type:r<.28?'cactus':r<.55?'rock':r<.78?'bush':'grass',scale:.7+rnd()*1.1})}

let audioCtx;
function sound(freq=.2,duration=.1,type='square',volume=.03){if(muted)return;try{audioCtx??=new(window.AudioContext||window.webkitAudioContext)();const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(volume,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+duration);o.connect(g);g.connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+duration)}catch(e){}}
function showToast(text,seconds=2){ui.toast.textContent=text;ui.toast.classList.remove('hidden');toastTimer=seconds}
function updateHud(){const count=fragments.filter(f=>f.got).length;$('hearts').innerHTML='';for(let i=0;i<player.maxHp;i++){const h=document.createElement('span');h.textContent=i<player.hp?'◆':'◇';$('hearts').append(h)}$('progress').style.width=(count/3*100)+'%';$('objective').textContent=count<3?`Encuentra las cartas · ${count}/3`:victory?'Derrota a Silas y vuelve a la campana':'Lucha: Silas Crowe está en el pueblo'}
function nearestEnemy(){let found=null,best=Infinity;for(const e of enemies){if(!e.alive)continue;const d=Math.hypot(e.x-player.x,e.y-player.y);if(d<best){best=d;found=e}}return found}

function resetGame(){seed=1887+Math.floor(rnd()*1000);player.x=480;player.y=390;player.hp=5;player.fire=0;player.invuln=0;player.walk=0;kills=0;victory=false;bullets=[];particles=[];camera={x:clamp(player.x-W/2,0,WORLD_W-W),y:clamp(player.y-H/2,0,WORLD_H-H)};fragments.forEach((f,i)=>{f.got=false});enemies.forEach((e,i)=>{e.alive=i<4;e.alert=false;e.hp=i===4?8:2;e.x=[300,610,720,370,522][i];e.y=[320,230,420,520,362][i]});updateHud()}
function startGame(){ui.title.classList.add('hidden');ui.end.classList.add('hidden');ui.pause.classList.add('hidden');ui.story.classList.remove('hidden');ui.hud.classList.remove('hidden');ui.touch.classList.remove('hidden');ui.tip.classList.remove('hidden');ui.topbar.style.opacity='.15';state='story';storyPage=0;cinematicTimer=0;resetGame();showStory()}
function showStory(){const page=storyPages[storyPage];ui.storyKicker.textContent=page[0];ui.storyCount.textContent=`0${storyPage+1} / 03`;ui.storyText.textContent='';cinematicTimer=0}
function advanceStory(){if(state!=='story')return;if(storyPage<storyPages.length-1){storyPage++;showStory()}else{ui.story.classList.add('hidden');ui.hud.classList.remove('hidden');ui.topbar.style.opacity='';state='play';showToast('ENCUENTRA LAS TRES CARTAS',3)}}
function togglePause(){if(state==='play'){state='paused';ui.pause.classList.remove('hidden');ui.touch.classList.add('hidden')}else if(state==='paused'){state='play';ui.pause.classList.add('hidden');ui.touch.classList.remove('hidden')}}
function endGame(won){state='ended';ui.touch.classList.add('hidden');ui.tip.classList.add('hidden');ui.end.classList.remove('hidden');ui.hud.classList.add('hidden');ui.endTitle.innerHTML=won?'LA CAMPANA<br /><em>VUELVE A SONAR</em>':'EL POLVO<br /><em>NO PERDONA</em>';ui.endCopy.textContent=won?'Red Rock recuerda tu nombre. Mara volvió a casa con la verdad.':'Silas Crowe domina una noche más. Respira, vuelve al camino.';sound(won?520:70,.5,won?'sine':'sawtooth',.05)}

function interact(){if(state!=='play')return;for(const f of fragments){if(!f.got&&Math.hypot(f.x-player.x,f.y-player.y)<34){f.got=true;const n=fragments.filter(v=>v.got).length;showToast(n<3?`CARTA ${n} DE 3 · UN NOMBRE: ${n===1?'ELENA':n===2?'JONAH':'MARA'}`:'LAS TRES CARTAS REUNIDAS',2.8);sound(690,.12,'sine');for(let i=0;i<16;i++)particles.push({x:f.x,y:f.y,vx:(rnd()-.5)*70,vy:(rnd()-.5)*70,life:.8,color:'#f4d18a'});if(n===3){const boss=enemies.find(e=>e.kind==='boss');boss.alive=true;boss.x=bell.x+42;boss.y=bell.y-8;boss.alert=true;showToast('SILAS CROWE TE ESPERA EN EL PUEBLO',3.3)}updateHud();return}}if(fragments.every(f=>f.got)&&victory&&Math.hypot(bell.x-player.x,bell.y-player.y)<65){endGame(true);return}const near=nearestEnemy();if(near&&Math.hypot(near.x-player.x,near.y-player.y)<42){showToast('¡DISPARA PARA ABRIRTE PASO!',1.4);return}if(Math.hypot(bell.x-player.x,bell.y-player.y)<66&&!fragments.every(f=>f.got))showToast('LAS CARTAS ESTÁN ESCONDIDAS POR EL DESIERTO',2)}
function shoot(dx,dy){if(player.fire>0)return;player.fire=.25;let ax=dx,ay=dy;if(!Number.isFinite(ax)||!Number.isFinite(ay)){const target=nearestEnemy();if(target&&Math.hypot(target.x-player.x,target.y-player.y)<260){ax=target.x-player.x;ay=target.y-player.y}else{ax=player.faceX;ay=player.faceY}}const m=Math.hypot(ax,ay)||1;ax/=m;ay/=m;player.faceX=ax;player.faceY=ay;bullets.push({x:player.x+ax*9,y:player.y+ay*8,vx:ax*240,vy:ay*240,life:.8});sound(125,.075,'sawtooth',.025);for(let i=0;i<3;i++)particles.push({x:player.x+ax*10,y:player.y+ay*8,vx:ax*(35+rnd()*40)+(rnd()-.5)*20,vy:ay*(35+rnd()*40)+(rnd()-.5)*20,life:.15+rnd()*.12,color:'#ffd580'})}
function hurt(){if(player.invuln>0)return;player.hp--;player.invuln=1.1;player.hitFlash=.22;showToast('¡CUIDADO, FORASTERA!',1.1);sound(90,.18,'square',.045);updateHud();const enemy=nearestEnemy();if(enemy){const dx=player.x-enemy.x,dy=player.y-enemy.y,d=Math.hypot(dx,dy)||1;player.x+=dx/d*13;player.y+=dy/d*13}if(player.hp<=0)setTimeout(()=>{if(state==='play')endGame(false)},450)}
function pollGamepad(){const gp=navigator.getGamepads?.()[0];if(!gp)return{mx:0,my:0,fire:false,interact:false,pause:false,aimX:0,aimY:0};const ax=gp.axes[0]||0,ay=gp.axes[1]||0,rx=gp.axes[2]||0,ry=gp.axes[3]||0;return{mx:Math.abs(ax)>.16?ax:0,my:Math.abs(ay)>.16?ay:0,fire:!!(gp.buttons[7]?.pressed||gp.buttons[2]?.pressed),interact:!!gp.buttons[0]?.pressed,pause:!!gp.buttons[9]?.pressed,aimX:Math.abs(rx)>.25?rx:0,aimY:Math.abs(ry)>.25?ry:0}}
let padPrev={a:false,start:false};

function update(dt){elapsed+=dt;if(toastTimer>0&&(toastTimer-=dt)<=0)ui.toast.classList.add('hidden');if(state==='story'){cinematicTimer+=dt;const full=storyPages[storyPage][1],count=Math.min(full.length,Math.floor(cinematicTimer*38));ui.storyText.textContent=full.slice(0,count);return}if(state!=='play')return;const gp=pollGamepad();if(gp.pause&&!padPrev.start)togglePause();if(gp.interact&&!padPrev.a)interact();padPrev={a:gp.interact,start:gp.pause};if(state!=='play')return;let mx=(keys.KeyD||keys.ArrowRight?1:0)-(keys.KeyA||keys.ArrowLeft?1:0),my=(keys.KeyS||keys.ArrowDown?1:0)-(keys.KeyW||keys.ArrowUp?1:0);mx+=touchMove.x+gp.mx;my+=touchMove.y+gp.my;const mag=Math.hypot(mx,my);if(mag>1){mx/=mag;my/=mag}if(mag>.08){player.faceX=mx;player.faceY=my;player.walk+=dt*12;player.x=clamp(player.x+mx*92*dt,12,WORLD_W-12);player.y=clamp(player.y+my*92*dt,12,WORLD_H-12)}player.fire=Math.max(0,player.fire-dt);player.invuln=Math.max(0,player.invuln-dt);player.hitFlash=Math.max(0,player.hitFlash-dt);const firing=keys.Space||keys.KeyJ||mouse.down||touchFire||gp.fire;if(firing){let ax=gp.aimX,ay=gp.aimY;if(mouse.active&&!touchFire){ax=mouse.x+camera.x-player.x;ay=mouse.y+camera.y-player.y}shoot(ax||undefined,ay||undefined)}if(keys.KeyE||keys.Enter||touchInteract){if(!update.interactHeld){interact();update.interactHeld=true}}else update.interactHeld=false;for(const e of enemies){if(!e.alive)continue;const d=Math.hypot(player.x-e.x,player.y-e.y),dx=(player.x-e.x)/(d||1),dy=(player.y-e.y)/(d||1);if(d<215)e.alert=true;if(e.alert&&d>21){e.x+=dx*e.speed*dt;e.y+=dy*e.speed*dt}e.phase+=dt*5;if(d<19&&Math.random()<dt*1.15)hurt()}for(const b of bullets){b.x+=b.vx*dt;b.y+=b.vy*dt;b.life-=dt;for(const e of enemies){if(!e.alive)continue;if(Math.hypot(b.x-e.x,b.y-e.y)<(e.kind==='boss'?13:9)){e.hp--;b.life=0;for(let i=0;i<5;i++)particles.push({x:b.x,y:b.y,vx:(rnd()-.5)*55,vy:(rnd()-.5)*55,life:.28+rnd()*.2,color:'#e2ad65'});if(e.hp<=0){e.alive=false;kills++;sound(220,.15,'triangle');if(e.kind==='boss'){victory=true;showToast('SILAS HA CAÍDO · VUELVE A LA CAMPANA',3.5)}else if(kills%3===0)showToast('EL CAMINO ESTÁ UN POCO MÁS LIBRE',1.8)}break}}}bullets=bullets.filter(b=>b.life>0);for(const p of particles){p.x+=p.vx*dt;p.y+=p.vy*dt;p.vx*=.96;p.vy*=.96;p.life-=dt}particles=particles.filter(p=>p.life>0);camera.x=clamp(player.x-W/2,0,Math.max(0,WORLD_W-W));camera.y=clamp(player.y-H/2,0,Math.max(0,WORLD_H-H));updateHud()}

function keyDown(e){if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Space'].includes(e.code))e.preventDefault();keys[e.code]=true;if(e.code==='Escape'||e.code==='KeyP'){if(state==='play'||state==='paused')togglePause()}if(state==='story'&&(e.code==='Enter'||e.code==='Space'))advanceStory()}function keyUp(e){keys[e.code]=false}
addEventListener('keydown',keyDown);addEventListener('keyup',keyUp);addEventListener('blur',()=>{for(const k in keys)keys[k]=false;mouse.down=false;touchFire=false});
canvas.addEventListener('pointermove',e=>{const r=canvas.getBoundingClientRect();mouse.x=(e.clientX-r.left)/r.width*W;mouse.y=(e.clientY-r.top)/r.height*H;if(e.pointerType==='mouse')mouse.active=true});canvas.addEventListener('pointerdown',e=>{if(state==='play'&&e.pointerType==='mouse'){mouse.down=true;mouse.active=true;canvas.setPointerCapture?.(e.pointerId)}else if(state==='story')advanceStory()});addEventListener('pointerup',()=>mouse.down=false);
$('startBtn').addEventListener('click',startGame);$('storyNext').addEventListener('click',advanceStory);$('resumeBtn').addEventListener('click',togglePause);$('restartBtn').addEventListener('click',startGame);$('againBtn').addEventListener('click',startGame);$('soundBtn').addEventListener('click',()=>{muted=!muted;$('soundBtn').textContent=muted?'♫':'♪';if(!muted)sound(440,.1,'sine')});
function bindHold(id,setter){const el=$(id);el.addEventListener('pointerdown',e=>{e.prevent.preventDefault?.();e.preventDefault();setter(true);el.setPointerCapture?.(e.pointerId)});el.addEventListener('pointerup',()=>setter(false));el.addEventListener('pointercancel',()=>setter(false));el.addEventListener('lostpointercapture',()=>setter(false))}bindHold('shootTouch',v=>touchFire=v);bindHold('interactTouch',v=>touchInteract=v);
const stickZone=$('stickZone'),stickKnob=$('stickKnob');let stickId=null;
stickZone.addEventListener('pointerdown',e=>{e.preventDefault();stickId=e.pointerId;stickZone.setPointerCapture(e.pointerId);moveStick(e)});stickZone.addEventListener('pointermove',e=>{if(e.pointerId===stickId)moveStick(e)});function moveStick(e){const r=stickZone.querySelector('.stick-base').getBoundingClientRect(),dx=e.clientX-(r.left+r.width/2),dy=e.clientY-(r.top+r.height/2),m=Math.hypot(dx,dy),lim=r.width*.34,s=Math.min(1,lim/(m||1));touchMove={x:dx*s/lim,y:dy*s/lim};stickKnob.style.transform=`translate(${dx*s}px,${dy*s}px)`}function resetStick(){stickId=null;touchMove={x:0,y:0};stickKnob.style.transform='translate(0,0)'}stickZone.addEventListener('pointerup',resetStick);stickZone.addEventListener('pointercancel',resetStick);

function rect(x,y,w,h,color){ctx.fillStyle=color;ctx.fillRect(Math.round(x),Math.round(y),Math.round(w),Math.round(h))}
function drawGround(){const x0=Math.max(0,Math.floor(camera.x/TILE)),y0=Math.max(0,Math.floor(camera.y/TILE)),x1=Math.min(MAP_W,Math.ceil((camera.x+W)/TILE)+1),y1=Math.min(MAP_H,Math.ceil((camera.y+H)/TILE)+1);for(let ty=y0;ty<y1;ty++)for(let tx=x0;tx<x1;tx++){const x=tx*TILE-camera.x,y=ty*TILE-camera.y,h=hash(tx,ty),base=h>.76?'#c79a5b':h<.1?'#bd8b51':'#c39254';rect(x,y,TILE,TILE,base);if(h>.56){rect(x+3,y+4,3,1,'#d7aa69');rect(x+10,y+12,2,1,'#a97b48')}else if(h<.27){rect(x+2,y+10,2,2,'#b8874d');rect(x+11,y+3,3,1,'#d1a063')}if(hash(tx+71,ty-21)>.975){rect(x+7,y+6,1,1,'#775f42');rect(x+8,y+7,1,1,'#775f42')}}ctx.lineCap='round';ctx.lineJoin='round';ctx.beginPath();ctx.moveTo(500-camera.x,380-camera.y);ctx.bezierCurveTo(448-camera.x,300-camera.y,548-camera.x,240-camera.y,480-camera.x,190-camera.y);ctx.bezierCurveTo(404-camera.x,130-camera.y,300-camera.x,188-camera.y,210-camera.x,152-camera.y);ctx.moveTo(486-camera.x,216-camera.y);ctx.bezierCurveTo(600-camera.x,154-camera.y,706-camera.x,178-camera.y,780-camera.x,145-camera.y);ctx.moveTo(484-camera.x,386-camera.y);ctx.bezierCurveTo(573-camera.x,431-camera.y,683-camera.x,480-camera.y,760-camera.x,520-camera.y);ctx.strokeStyle='#aa7949';ctx.lineWidth=13;ctx.stroke();ctx.strokeStyle='#d2a467';ctx.lineWidth=8;ctx.stroke()}
