function drawLandmarks(){for(const f of fragments){const x=f.x-camera.x,y=f.y-camera.y;if(x<-40||x>W+40||y<-40||y>H+40)continue;if(f.place==='Cementerio'){rect(x-30,y-15,60,31,'#b58a54');for(let i=0;i<5;i++){const gx=x-23+i*12,gy=y-6+(i%2)*10;rect(gx-1,gy-4,8,6,'#8e7757');rect(gx+1,gy-8,4,10,'#a99774');rect(gx+2,gy-7,1,5,'#d1ba8b')}rect(x-28,y+15,57,2,'#745a3d');rect(x-26,y+18,2,7,'#785940');rect(x+26,y+18,2,7,'#785940');ctx.fillStyle='#6d4c32';ctx.font='5px monospace';ctx.textAlign='center';ctx.fillText('R.I.P.',x,y+27)}if(f.place==='Mina abandonada'){rect(x-31,y-13,62,28,'#b38a54');rect(x-24,y-6,48,20,'#554637');rect(x-20,y-5,40,17,'#272d28');rect(x-28,y-13,56,5,'#71563a');rect(x-27,y-16,3,14,'#755638');rect(x+24,y-16,3,14,'#755638');rect(x-28,y-18,55,3,'#8b6842');rect(x-4,y-15,8,7,'#d3a85e');ctx.fillStyle='#e2c28a';ctx.font='5px monospace';ctx.textAlign='center';ctx.fillText('MINA',x,y+25)}if(f.place==='Oasis seco'){rect(x-32,y-15,64,28,'#a67b4c');rect(x-24,y-9,48,16,'#896d49');rect(x-20,y-7,40,12,'#51766b');rect(x-14,y-4,26,6,'#78a18a');rect(x+13,y-12,9,13,'#4e4b30');rect(x+16,y-20,3,12,'#3c563a');rect(x+9,y-20,12,3,'#4d6840');rect(x+16,y-24,3,6,'#617441');ctx.fillStyle='#e2c28a';ctx.font='5px monospace';ctx.textAlign='center';ctx.fillText('OASIS',x,y+22)}if(!f.got){const bob=Math.sin(elapsed*3+f.phase)*2;rect(x-3,y-14+bob,6,8,'#e9d29b');rect(x-2,y-13+bob,4,6,'#fff0c1');rect(x-6,y-16+bob,12,1,'#f1d98f');if(Math.sin(elapsed*4+f.phase)>.75){ctx.strokeStyle='#f8e2a8';ctx.strokeRect(x-9,y-20+bob,18,19)}}}}
function drawProp(p){const x=Math.round(p.x-camera.x),y=Math.round(p.y-camera.y);if(x<-20||x>W+20||y<-20||y>H+20)return;const s=p.scale;rect(x-5*s,y+3*s,10*s,3*s,'#987142');if(p.type==='cactus'){rect(x-2*s,y-9*s,4*s,13*s,'#466044');rect(x-5*s,y-6*s,3*s,7*s,'#55704b');rect(x-5*s,y-6*s,4*s,3*s,'#55704b');rect(x+2*s,y-4*s,3*s,6*s,'#486245');rect(x+1*s,y-4*s,4*s,3*s,'#486245');rect(x-1*s,y-8*s,1*s,8*s,'#789164')}else if(p.type==='rock'){rect(x-6*s,y-2*s,12*s,5*s,'#78674e');rect(x-4*s,y-5*s,8*s,5*s,'#927d5c');rect(x-1*s,y-4*s,2*s,2*s,'#b29a6e')}else if(p.type==='bush'){rect(x-6*s,y-2*s,12*s,5*s,'#665c37');rect(x-5*s,y-6*s,6*s,5*s,'#68713f');rect(x,y-8*s,6*s,6*s,'#596b3c');rect(x-1*s,y-6*s,2*s,2*s,'#899050')}else{rect(x-6*s,y,12*s,2*s,'#e0c58d');rect(x-3*s,y-3*s,7*s,2*s,'#cfb37e');rect(x+3*s,y-5*s,3*s,2*s,'#e0c58d')}}

