const ws = new WebSocket(target.webSocketDebuggerUrl);
let id=0; const pending=new Map(); const errors=[];
ws.addEventListener('message', e=>{const m=JSON.parse(e.data);if(m.id){const p=pending.get(m.id);if(p){pending.delete(m.id);p(m)}}else if(m.method==='Runtime.exceptionThrown'){errors.push(m.params.exceptionDetails.text)}});
await new Promise((resolve,reject)=>{ws.addEventListener('open',resolve,{once:true});ws.addEventListener('error',reject,{once:true})});
function call(method,params={}){return new Promise(resolve=>{const n=++id;pending.set(n,resolve);ws.send(JSON.stringify({id:n,method,params}))})}
await call('Runtime.enable'); await call('Page.enable');
async function ev(expression){const r=await call('Runtime.evaluate',{expression,returnByValue:true,awaitPromise:true});if(r.result.exceptionDetails)throw Error(r.result.exceptionDetails.text);return r.result.result.value}
